input.mermaid:
stateDiagram-v2
  [*] --> IDLE

  state IDLE {
    [*] --> IdleStandby
    IdleStandby --> SocialConsent : 短按开始(社交模式)
    IdleStandby --> VoiceListening : 按键唤起(语音助手)
  }

  state SocialConsent {
    [*] --> ConsentDisplay : 显示隐私提示
    ConsentDisplay --> Recording : 用户确认
    ConsentDisplay --> IDLE : 取消
  }

  state Recording {
    [*] --> Streaming
    Streaming --> Finalizing : 短按结束
    Streaming --> Cancelled : 长按取消
    Streaming --> Error : 异常(网络/内存)
  }

  state Finalizing {
    [*] --> WaitingResult
    WaitingResult --> ResultReady : 云端返回完整结果
    WaitingResult --> Cancelled : 取消
    WaitingResult --> Error : 超时/失败
  }

  state ResultReady {
    [*] --> DisplayResult
    DisplayResult --> IDLE : 确认完成
  }

  state Cancelled {
    [*] --> Cleanup
    Cleanup --> IDLE : 释放资源
  }

  state Error {
    [*] --> ErrorDisplay
    ErrorDisplay --> IDLE : 返回待机
  }

  state VoiceListening {
    [*] --> MicCapture
    MicCapture --> Transcribing : 按键结束录音
    MicCapture --> Cancelled : 取消
    MicCapture --> IDLE : 超时无语音
  }

  state Transcribing {
    [*] --> ASRWait
    ASRWait --> Thinking : ASR成功
    ASRWait --> Cancelled : 取消/失败
  }

  state Thinking {
    [*] --> LLMWait
    LLMWait --> Speaking : 模型返回回答
    LLMWait --> Cancelled : 取消/失败
  }

  state Speaking {
    [*] --> TTSPlay
    TTSPlay --> IDLE : 播报完成
    TTSPlay --> Cancelled : 按键打断
  }

